import{_ as a,o as e,c as i,a3 as t}from"./chunks/framework.DIhSGQkP.js";const u=JSON.parse('{"title":"Simulator and scripts","description":"","frontmatter":{},"headers":[],"relativePath":"developers/simulator.md","filePath":"developers/simulator.md"}'),o={name:"developers/simulator.md"};function n(l,s,p,r,c,d){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="simulator-and-scripts" tabindex="-1">Simulator and scripts <a class="header-anchor" href="#simulator-and-scripts" aria-label="Permalink to &quot;Simulator and scripts&quot;">​</a></h1><h2 id="loopback" tabindex="-1"><code>--loopback</code> <a class="header-anchor" href="#loopback" aria-label="Permalink to &quot;\`--loopback\`&quot;">​</a></h2><p><code>--loopback</code> runs the same editor protocol against an in-process simulator. Framing, CRC, and commands match a real device. Transport and device state are simulated.</p><p>Use it for:</p><ul><li>Examples you can paste without a board</li><li>Continuous integration</li><li>Multi-step experiments in one process (<code>repl</code> or <code>--script</code>)</li></ul><p>Limits:</p><ul><li><strong>Per-process state.</strong> Each <code>s32 --loopback …</code> invocation starts fresh (three demo projects named Project 1–3).</li><li><strong>Fixture schema.</strong> Device types are a short stand-in. Capture live tables with <code>--usb</code> and <code>schema --emit-schema-json</code>.</li><li>Onboard storage is modeled; raw microSD project read/write may be reported as unavailable depending on firmware.</li></ul><h2 id="hardware-coverage-physical-s32" tabindex="-1">Hardware coverage (physical S32) <a class="header-anchor" href="#hardware-coverage-physical-s32" aria-label="Permalink to &quot;Hardware coverage (physical S32)&quot;">​</a></h2><p><code>--loopback</code> is the CI path. To run the same command coverage on a plugged-in S32, quit the web editor first (USB is exclusive), then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/webeditor-sim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USE_LIBUSB=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run-hardware</span></span></code></pre></div><p>See <code>tools/webeditor-sim/README.md</code> for flags and what the run restores.</p><h2 id="script" tabindex="-1"><code>--script</code> <a class="header-anchor" href="#script" aria-label="Permalink to &quot;\`--script\`&quot;">​</a></h2><p>Every line is <code>command args…</code>. <code>#</code> starts a comment. The run exits non-zero if a line fails. Destructive commands do <strong>not</strong> prompt.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.script</span></span></code></pre></div><p>Example <code>session.script</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello</span></span>
<span class="line"><span>list</span></span>
<span class="line"><span>macro get 0 0</span></span>
<span class="line"><span>macro set 4 1 mode=cc msb=74 channel=3</span></span>
<span class="line"><span>potname set 4 Cutoff</span></span></code></pre></div><h2 id="repl" tabindex="-1">REPL <a class="header-anchor" href="#repl" aria-label="Permalink to &quot;REPL&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback</span></span>
<span class="line"><span>s32&gt; hello</span></span>
<span class="line"><span>s32&gt; list</span></span>
<span class="line"><span>s32&gt; macro get 0 0</span></span>
<span class="line"><span>s32&gt; quit</span></span></code></pre></div><p>On a TTY with no command, <code>s32</code> opens a REPL after connecting. <code>s32 repl</code> does the same. USB stays open for the whole session.</p><h2 id="layout-json" tabindex="-1">Layout JSON <a class="header-anchor" href="#layout-json" aria-label="Permalink to &quot;Layout JSON&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> layout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-layout-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s32-layout.json</span></span></code></pre></div><p>Writes struct sizes and field offsets for the project record this CLI was built against. No board and no simulator session are required.</p>`,22)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
